    css: "* {\n\tmargin: 0;\n\tpadding: 0;\n\tbox-sizing: border-box;\n}\n\nbody,\nhtml {\n\twidth: 100%;\n\theight: 100%;\n}\n\nbody {\n\tdisplay: grid;\n\tplace-content: center;\n\tbackground: #1e1f26;\n}\n\n.container {\n\theight: 700px;\n\tborder-radius: 3px;\n\tpadding-top:20em;\n\tborder-radius: 10px;\n\n\t.app-bar {\n\t\tdisplay: flex;\n\t\talign-items: flex-start;\n\t\tjustify-content: center;\n\t\t/* \t\tborder: 5px solid #fff; */\n\t\tbackground: rgba(218, 6, 7, 0.78);\n\t\twidth: max-content;\n\t\tmargin: 0 auto 30px auto;\n\t\tborder-radius: 50px;\n\t\t-webkit-box-reflect: below 2px;\n\t\t.svg-box-item {\n\t\t\tpadding: 10px;\n\t\t\twidth: 50px;\n\t\t\theight: 50px;\n\t\t\tcursor: pointer;\n\t\t\tz-index: 1;\n\t\t\tcolor: #fff;\n\t\t\tsvg {\n\t\t\t\ttransition: all 233ms;\n\t\t\t\ttransform-origin: bottom center;\n\t\t\t\twidth: 100%;\n\t\t\t\theight: 100%;\n\t\t\t}\n\t\t}\n\t\t:has(~ .svg-box-item:hover) {\n\t\t\topacity: 0.5;\n\t\t}\n\t\t:has(+ .svg-box-item:hover) svg {\n\t\t\ttransform: translatey(-20px) scale(1.5) rotate(-15deg);\n\t\t\tcolor: #ff6347;\n\t\t}\n\t\t.svg-box-item:hover svg {\n\t\t\ttransform: translatey(-40px) scale(2.3);\n\t\t\tcolor: #ffd700;\n\t\t}\n\t\t.svg-box-item:hover + .svg-box-item svg {\n\t\t\ttransform: translatey(-20px) scale(1.5) rotate(15deg);\n\t\t\tcolor: #00ff00;\n\t\t}\n\t\t.svg-box-item:hover ~ .svg-box-item {\n\t\t\topacity: 0.5;\n\t\t}\n\n\t\t.svg-box-more {\n\t\t\tcursor: pointer;\n\t\t\twidth: 100px;\n\t\t\theight: 50px;\n\t\t\tborder-radius: 100%;\n\t\t\tposition: relative;\n\t\t\ttransition: all 150ms;\n\t\t\t&::after {\n\t\t\t\tcontent: \"⚪⚪⚪\";\n\t\t\t\tposition: absolute;\n\t\t\t\tinset: 0;\n\t\t\t\ttext-align: center;\n\t\t\t\talign-content: center;\n\t\t\t}\n\t\t\t&:hover {\n\t\t\t\tletter-spacing: -1em;\n\t\t\t\t.svg-box {\n\t\t\t\t\topacity: 1;\n\t\t\t\t}\n\t\t\t\t.svg-box:nth-child(1) {\n\t\t\t\t\toffset-distance: 28%;\n\t\t\t\t}\n\t\t\t\t.svg-box:nth-child(2) {\n\t\t\t\t\toffset-distance: 46%;\n\t\t\t\t}\n\t\t\t\t.svg-box:nth-child(3) {\n\t\t\t\t\toffset-distance: 64%;\n\t\t\t\t}\n\t\t\t\t.svg-box:nth-child(4) {\n\t\t\t\t\toffset-distance: 82%;\n\t\t\t\t}\n\t\t\t\t.svg-box:nth-child(5) {\n\t\t\t\t\toffset-distance: 100%;\n\t\t\t\t}\n\t\t\t}\n\t\t\t.svg-box {\n\t\t\t\t--bounce-easing: linear(\n\t\t\t\t\t0,\n\t\t\t\t\t0.0157,\n\t\t\t\t\t0.0625 9.09%,\n\t\t\t\t\t0.25,\n\t\t\t\t\t0.5625,\n\t\t\t\t\t1,\n\t\t\t\t\t0.8125 45.45%,\n\t\t\t\t\t0.7657,\n\t\t\t\t\t0.75,\n\t\t\t\t\t0.7657,\n\t\t\t\t\t0.8125 63.64%,\n\t\t\t\t\t1 72.73%,\n\t\t\t\t\t0.9532,\n\t\t\t\t\t0.9375,\n\t\t\t\t\t0.9531,\n\t\t\t\t\t1,\n\t\t\t\t\t0.9844,\n\t\t\t\t\t1\n\t\t\t\t);\n\t\t\t\tpadding: 10px;\n\t\t\t\twidth: 50px;\n\t\t\t\theight: 50px;\n\t\t\t\tcursor: pointer;\n\t\t\t\tz-index: 1;\n\t\t\t\tcolor: #fff;\n\t\t\t\tposition: absolute;\n\t\t\t\ttop: 50%;\n\t\t\t\tleft: 50%;\n\t\t\t\ttransform: translate(-50%, -50%);\n\t\t\t\ttransition: all 1000ms;\n\t\t\t\ttransition-timing-function: var(--bounce-easing);\n\t\t\t\toffset-path: path(\"M 20,-50 Q -70,-250 110,-300\");\n\t\t\t\toffset-distance: 0%;\n\t\t\t\topacity: 0;\n\t\t\t\tbackground: rgba(218, 6, 7, 0.78);\n\t\t\t\tborder-radius: 100%;\n\t\t\t}\n\t\t\t.svg-box:nth-child(5) {\n\t\t\t\ttransition-delay: 0ms;\n\t\t\t}\n\t\t\t.svg-box:nth-child(4) {\n\t\t\t\ttransition-delay: 40ms;\n\t\t\t}\n\t\t\t.svg-box:nth-child(3) {\n\t\t\t\ttransition-delay: 80ms;\n\t\t\t}\n\t\t\t.svg-box:nth-child(2) {\n\t\t\t\ttransition-delay: 120ms;\n\t\t\t}\n\t\t\t.svg-box:nth-child(1) {\n\t\t\t\ttransition-delay: 160ms;\n\t\t\t}\n\t\t}\n\t}\n}\n",
