    css: "* {\n\tmargin: 0;\n\tpadding: 0;\n\tuser-select: none;\n\t.out-box {\n\t\twidth: 100%;\n\t\theight: 1080px;\n\t\tbackground: #1d1e22;\n\t\tmargin: 0;\n\t\tpadding-top: 50px;\n\t\t.svg-box {\n\t\t\tposition: relative;\n\t\t\twidth: 500px;\n\t\t\theight: 50px;\n\t\t\tmargin: 50px auto;\n\t\t\tdisplay: flex;\n\t\t\t.svg-box-item {\n\t\t\t\tcursor: pointer;\n\t\t\t\tposition: relative;\n\t\t\t\tz-index: 1;\n\t\t\t\tflex: 1;\n\t\t\t\tcolor: #fff;\n\t\t\t\tsvg {\n\t\t\t\t\twidth: 100%;\n\t\t\t\t\theight: 100%;\n\t\t\t\t}\n\t\t\t}\n\t\t\t.svg-box-item:nth-child(1):hover ~ .svg-position-item {\n\t\t\t\tbackground: rgb(221, 238, 66);\n\t\t\t\tleft: 0;\n\t\t\t\tbox-shadow: rgba(221, 238, 66, 0.56) 0px 22px 70px 4px;\n\t\t\t}\n\t\t\t.svg-box-item:nth-child(2):hover ~ .svg-position-item {\n\t\t\t\tbackground: rgb(244, 92, 37);\n\t\t\t\tleft: 100px;\n\t\t\t\tbox-shadow: rgba(244, 92, 37, 0.56) 0px 22px 70px 4px;\n\t\t\t}\n\t\t\t.svg-box-item:nth-child(3):hover ~ .svg-position-item {\n\t\t\t\tbackground: rgb(59, 150, 235);\n\t\t\t\tleft: 200px;\n\t\t\t\tbox-shadow: rgba(59, 150, 235, 0.56) 0px 22px 70px 4px;\n\t\t\t}\n\t\t\t.svg-box-item:nth-child(4):hover ~ .svg-position-item {\n\t\t\t\tbackground: rgb(240, 59, 201);\n\t\t\t\tleft: 300px;\n\t\t\t\tbox-shadow: rgba(240, 59, 201, 0.56) 0px 22px 70px 4px;\n\t\t\t}\n\t\t\t.svg-box-item:nth-child(5):hover ~ .svg-position-item {\n\t\t\t\tbackground: rgb(158, 32, 232);\n\t\t\t\tleft: 400px;\n\t\t\t\tbox-shadow: rgba(158, 32, 232, 0.56) 0px 22px 70px 4px;\n\t\t\t}\n\t\t\t.svg-position-item {\n\t\t\t\tposition: absolute;\n\t\t\t\twidth: 100px;\n\t\t\t\theight: 100px;\n\t\t\t\ttop: -50%;\n\t\t\t\tleft: 0;\n\t\t\t\tborder-radius: 10%;\n\t\t\t\ttransition: all 0.3s ease-in-out;\n\t\t\t}\n\t\t}\n\t}\n}\n",
