    css: "* {\n\tmargin: 0;\n\tpadding: 0;\n\tbox-sizing: border-box;\n}\n\nbody,\nhtml {\n\twidth: 100%;\n\theight: 100%;\n}\n\nbody {\n\tdisplay: flex;\n\tflex-direction: column;\n\talign-items: center;\n\tjustify-content: center;\n\tgap: 1vh;\n\tbackground: #1e1f26;\n}\n\n.container {\n\twidth: 500px;\n\theight: 350px;\n\tborder-radius: 3px;\n\tbackground: #3a3a72;\n}\n\n.container {\n\tcursor: pointer;\n\tposition: relative;\n\toverflow: hidden;\n}\n\n.free .line {\n\tposition: absolute;\n\ttop: 50%;\n\tleft: calc(50% - 85px);\n\twidth: 170px;\n\theight: 2px;\n\tbackground: #fff;\n\tanimation-name: rotateReverse;\n\tanimation-duration: 5s;\n\tanimation-direction: alternate;\n\tanimation-iteration-count: infinite;\n\tanimation-timing-function: ease-in-out;\n}\n\n@keyframes rotateReverse {\n\t33.33% {\n\t\ttransform-origin: left center;\n\t\trotate: 360deg;\n\t}\n\t66.66% {\n\t\ttransform-origin: right center;\n\t\trotate: -360deg;\n\t}\n}\n\n.gemini {\n\t.line {\n\t\tposition: absolute;\n\t\ttop: 50%;\n\t\twidth: 170px;\n\t\theight: 2px;\n\t\tbackground: #fff;\n\t\tanimation-duration: 5s;\n\t\tanimation-direction: alternate;\n\t\tanimation-iteration-count: infinite;\n\t\tanimation-timing-function: ease-in-out;\n\t\tanimation-name: rotateLeft;\n\t}\n\t.line-left {\n\t\ttransform-origin: left center;\n\t\tleft: 50%;\n\t}\n\t.line-right {\n\t\ttransform-origin: right center;\n\t\tright: 50%;\n\t}\n\n\t.line-left-reverse {\n\t\twidth: 100px;\n\t\ttransform-origin: right center;\n\t}\n\t.line-right-reverse {\n\t\twidth: 100px;\n\t\ttransform-origin: left center;\n\t}\n}\n\n@keyframes rotateLeft {\n\t25% {\n\t\trotate: 180deg;\n\t}\n\t50% {\n\t\trotate: 0deg;\n\t}\n\t60% {\n\t\trotate: 0deg;\n\t}\n\t75% {\n\t\trotate: -180deg;\n\t}\n\t90% {\n\t\trotate: 0deg;\n\t}\n\t100% {\n\t\trotate: 0deg;\n\t}\n}\n\n.line-1 {\n\tanimation-delay: -0.1s;\n}\n.line-2 {\n\tanimation-delay: -0.2s;\n}\n.line-3 {\n\tanimation-delay: -0.3s;\n}\n.line-4 {\n\tanimation-delay: -0.4s;\n}\n.line-5 {\n\tanimation-delay: -0.5s;\n}\n.line-6 {\n\tanimation-delay: -0.6s;\n}\n.line-7 {\n\tanimation-delay: -0.7s;\n}\n",
