    css: "* {\n\tmargin: 0;\n\tpadding: 0;\n\tbox-sizing: border-box;\n}\n\nbody,\nhtml {\n\twidth: 100%;\n\theight: 100%;\n}\n\nbody {\n\tdisplay: grid;\n\tplace-content: center;\n\tbackground: #1e1f26;\n}\n\n.container {\n\tposition: relative;\n\theight: 80vmin;\n\taspect-ratio: 0.4615384615;\n\tbackground: #6a2d7b;\n\t.ripple {\n\t\tposition: absolute;\n\t\tinset: 10% 5%;\n\t\tbackground: #6eb136;\n\t\tborder-radius: 26% / 14%;\n\t}\n\t.ripple:not(.ripple1) {\n\t\tinset: 4% 1% 4% 4%;\n\t}\n\t.ripple2 {\n\t\tbackground: #f7c264;\n\t}\n\t.ripple3 {\n\t\tbackground: #b6d9b8;\n\t}\n\t.ripple4 {\n\t\tbackground: #6cbba3;\n\t}\n\t.ripple5 {\n\t\tbackground: #29a3a5;\n\t}\n\t.ripple6 {\n\t\tbackground: #217793;\n\t}\n\t.ripple7 {\n\t\tbackground: #1c4771;\n\t}\n\t.ripple8 {\n\t\tbackground: #1f2562;\n\t}\n\t.ripple9 {\n\t\tbackground: #011535;\n\t}\n}\n",
